  showTopicDetails(topic, subtopicId, index) {
    if (this.assessmentActive && this._currentBlock.selectionType === 'AUTOMATED') {
      return;
    }

    this.showFilter = false;
    let subtopicName = '';
    this.selectedTopic = topic;
    this.selectedSubtopicId = subtopicId;
    this.itemService.topicId = topic.topicId;
    this.itemService.subtopicId = topic.subtopicId;

    if (this.assessmentActive && this._currentBlock.selectionType === 'AUTOMATED') {
      this.fetchItems(topic);
      this.selectedSubtopic = '';
      this.clickedTopic = topic; // return;
    }

    if (subtopicId) {
      this.fetchItems(topic, subtopicId);
      topic.subtopics.filter((subtopic, position) => {
        if (index === position) {
          this.clickedTopic = Object.assign({
            topic
          }, subtopic); // console.log(this.clickedTopic);

          subtopicName = subtopic.subtopicName;
          this.selectedSubtopic = subtopicName;
        }
      });
    } else {
      this.fetchItems(topic);
      this.selectedSubtopic = '';
      this.clickedTopic = topic; // console.log('selected topic', this.clickedTopic);
    }

    let itemTrail = {
      subjectId: this.itemService.subjectId,
      subjectName: this.subjectName,
      topicId: topic.topicId,
      topicName: topic.topicName,
      subtopicId: subtopicId,
      subtopicName: subtopicName
    };
    this.itemProps = itemTrail;
    this.itemUtil.currentItemTrail = itemTrail;
    this.itemUtil.saveCurrentItemTrail();
  }

  saveTopicSelection(topic, subtopicId, subtopicName = '') {
    // Build itemTrail containing subjectId, subjectName, topicId, topicName, subtopicId, and subtopicName
    let itemTrail = {
      subjectId: this.itemService.subjectId,
      subjectName: this.subjectName,
      topicId: topic.topicId,
      topicName: topic.topicName,
      subtopicId: subtopicId,
      subtopicName: subtopicName
    }; // Assign itemTrail to this.itemProps and this.itemUtil.currentItemTrail

    this.itemProps = itemTrail;
    this.itemUtil.currentItemTrail = itemTrail; // Call this.itemUtil.saveCurrentItemTrail()

    this.itemUtil.saveCurrentItemTrail();
  }

  fetchItems(topic, subtopicId) {
    // console.log("fetch items called here");
    this.loading_items = true;
    this.pageNo = 0;
    this.pageSize = 20;
    this.currentTopic = topic;
    this.currentExistingTopic = Object.assign({}, topic);

    if (this.assessmentActive && this._sectionId) {
      this.itemService.fetchAllAssessmentItems(this._assessmentId, this._sectionId, this.itemService.subjectId, topic.topicId, subtopicId, this.pageNo, this.pageSize).subscribe(value => {
        this.itemsPage = value;
        this.itemsPage.content.forEach(item => {
          item.showFullItem = false;
          item.showingPreviewLoader = false;
        });
        this.loading_items = false; // console.log(this.itemsPage.content);
      }, error => {
        // console.log(error);
        this.loading_items = false;
      });
    } else {
      this.itemService.fetchAllItems(this.itemService.subjectId, topic === null || topic === void 0 ? void 0 : topic.topicId, subtopicId, this.pageNo, this.pageSize).subscribe(value => {
        this.itemsPage = value;
        this.itemsPage.content.forEach(item => {
          item.showFullItem = false;
          item.stimulusSafeHtml = this.domSanitizer.bypassSecurityTrustHtml(this.itemService.sanitize(item.stimulus)); // Store a plain string version for previewing

          item.stimulusPreview = item.stimulus.slice(0, 50);
        });
        this.loading_items = false; // console.log(this.itemsPage.content);
      }, error => {
        // console.log(error);
        this.loading_items = false;
      });
    }
  }

