class SubjectNotificationsComponent {
    constructor(ar, notificationService, notifier, itemService, modalService, router) {
        this.ar = ar;
        this.notificationService = notificationService;
        this.notifier = notifier;
        this.itemService = itemService;
        this.modalService = modalService;
        this.router = router;
        this.page = 0;
        this.pageSize = 25;
        this.loading = true;
    }
    ngOnInit() {
        this.subject = this.itemService.subjectName;
        this.subjectId = this.ar.snapshot.params['id'];
        this.status = this.ar.snapshot.params['stats'].toUpperCase();
        this.breadCrumbItems = [
            { label: 'subjects', active: false },
            { label: this.subject, active: false },
            { label: this.status.toLowerCase(), active: true },
        ];
        this.notificationService
            .filterNotificationsBySubject(this.status, this.subjectId)
            .subscribe((value) => {
            if (value) {
                this.notifications = value;
                this.loading = false;
            }
        }, (error) => {
            this.notifier.notify('error', `${error.error.message}`);
            this.loading = false;
        });
    }
    openNotification(notification) {
        // console.log(notification);
        this.router.navigate(['/examalpha/subjects/' + notification.subjectName + '/edit-item'], {
            queryParams: {
                type: `${notification.itemType}`,
                id: `${notification.itemId}`,
            },
        });
    }
    openPreviewItemModal(notification, itemModal) {
        this.itemService.fetchIndividualItem(notification.itemId).subscribe((value) => {
            if (value) {
                this.item = value;
            }
        }, (error) => {
            // console.log(error.error.message);
        });
        this.modalService.open(itemModal, { centered: true, size: 'lg' });
    }
    onPageChange(event) {
        this.page = event.page;
        this.pageSize = event.rows;
        this.ngOnInit();
    }
}
